    const NORMAL: u8 = 1;
    const RETURN: u8 = 2;
    const ESCAPE: u8 = 4;
    const LOCAL: u8 = 8;
    fn sequence(left: u8, right: impl FnOnce() -> u8) -> u8 {
        (left & !NORMAL) | if left & NORMAL != 0 { right() } else { 0 }
