                }
            }
            _ => {
                frames[depth - 1].1 += 1;
                crate::hir::lexical_exit::child(expression, next)
            }
        };
        if let Some(child) = child {
            if depth == CENSUS_DEPTH {
                return Err(error());
            }
            frames[depth] = (child, 0, 0);
            depth += 1;
        } else {
            depth -= 1;
        }
    }
    Ok(found)
}

